SELECT 'ADMIN', (SELECT id FROM tenants WHERE code = 'default'), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'liquibase', 'liquibase', 0
WHERE NOT EXISTS (SELECT 1 FROM roles WHERE code = 'ADMIN' AND tenant_id = (SELECT id FROM tenants WHERE code = 'default'));

